CREATE TABLE IF NOT EXISTS student_attendance (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), attendance_date TEXT NOT NULL, class_id TEXT REFERENCES classes(id), student_id TEXT NOT NULL REFERENCES student_profiles(id), subject_id TEXT REFERENCES subjects(id), status TEXT NOT NULL, method TEXT NOT NULL, arrival_time TEXT, departure_time TEXT, reason TEXT, version INTEGER NOT NULL DEFAULT 1, entered_by TEXT NOT NULL REFERENCES users(id), entered_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(school_id, attendance_date, student_id, subject_id));
CREATE TABLE IF NOT EXISTS staff_attendance (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), staff_id TEXT NOT NULL REFERENCES staff(id), attendance_date TEXT NOT NULL, attendance_type TEXT NOT NULL, attendance_time TEXT, entered_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS attendance_notification_settings (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), parent_user_id TEXT NOT NULL REFERENCES users(id), absence_enabled INTEGER NOT NULL DEFAULT 1, lateness_enabled INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL, UNIQUE(school_id, parent_user_id));
CREATE TABLE IF NOT EXISTS attendance_sync_conflicts (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), attendance_id TEXT REFERENCES student_attendance(id), client_version INTEGER, server_version INTEGER, client_payload TEXT NOT NULL, detected_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_student_attendance_class_date ON student_attendance(school_id, class_id, attendance_date);
CREATE INDEX IF NOT EXISTS idx_student_attendance_student_date ON student_attendance(student_id, attendance_date);
